// Generates a FASTA file: 50 records of 100,000 bases each, seeded mulberry32 PRNG (seed 9).
import { writeFileSync } from "node:fs";

const SEED = 9;
const RECORDS = 50;
const BASES_PER_RECORD = 100_000;
const LINE_WIDTH = 60;
const OUT = "sample.fa";

/** mulberry32 seeded PRNG -> [0, 1) */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const BASES = ["A", "C", "G", "T"] as const;

function randomSeq(len: number, rnd: () => number): string {
  const out = new Array<string>(len);
  for (let i = 0; i < len; i++) {
    out[i] = BASES[(rnd() * 4) | 0];
  }
  return out.join("");
}

function main(): void {
  const rnd = mulberry32(SEED);
  const chunks: string[] = [];
  for (let r = 0; r < RECORDS; r++) {
    chunks.push(`>seq${String(r + 1).padStart(3, "0")}`);
    const seq = randomSeq(BASES_PER_RECORD, rnd);
    for (let i = 0; i < seq.length; i += LINE_WIDTH) {
      chunks.push(seq.slice(i, i + LINE_WIDTH));
    }
  }
  writeFileSync(OUT, chunks.join("\n") + "\n");
  console.log(`Wrote ${OUT}: ${RECORDS} records x ${BASES_PER_RECORD} bases`);
}

main();

