// Streaming k-mer counter: counts plain (non-canonical) k-mers per record and globally.
import { createReadStream } from "node:fs";
import { createInterface } from "node:readline";

export interface KmerResult {
  globalCounts: Map<string, number>;
  perRecordCounts: Map<string, Map<string, number>>;
  totalWindows: number;
}

/** Count plain k-mers in a sequence string, adding into `counts`. Returns windows added. */
export function countKmers(seq: string, k: number, counts: Map<string, number>): number {
  let added = 0;
  for (let i = 0; i + k <= seq.length; i++) {
    const km = seq.slice(i, i + k);
    counts.set(km, (counts.get(km) ?? 0) + 1);
    added++;
  }
  return added;
}

/**
 * Stream a FASTA file line-by-line with node:readline, counting k-mers per record
 * (headers reset the per-record window; k-mers never span records).
 */
export async function countFastaKmers(path: string, k: number): Promise<KmerResult> {
  const globalCounts = new Map<string, number>();
  const perRecordCounts = new Map<string, Map<string, number>>();
  const rl = createInterface({ input: createReadStream(path), crlfDelay: Infinity });

  let currentId = "";
  for await (const line of rl) {
    if (line.startsWith(">")) {
      currentId = line.slice(1).trim();
      perRecordCounts.set(currentId, new Map());
    } else if (line.length > 0) {
      const counts = perRecordCounts.get(currentId)!;
      countKmers(line, k, counts);
    }
  }
  for (const m of perRecordCounts.values()) {
    for (const [km, c] of m) {
      globalCounts.set(km, (globalCounts.get(km) ?? 0) + c);
    }
  }
  let totalWindows = 0;
  for (const c of globalCounts.values()) totalWindows += c;

  return { globalCounts, perRecordCounts, totalWindows };
}

export function topK(counts: Map<string, number>, n: number): Array<[string, number]> {
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, n);
}

async function main(): Promise<void> {
  const file = process.argv[2] ?? "sample.fa";
  const k = Number(process.argv[3] ?? 8);
  const started = Date.now();
  const { globalCounts, totalWindows } = await countFastaKmers(file, k);
  console.log(`k=${k}, distinct=${globalCounts.size}, totalWindows=${totalWindows}`);
  console.log("Top 10:");
  for (const [km, c] of topK(globalCounts, 10)) {
    console.log(`${km}\t${c}`);
  }
  console.error(`Elapsed: ${((Date.now() - started) / 1000).toFixed(2)}s`);
}

if (process.argv[1] && process.argv[1].endsWith("kmer.ts")) {
  main();
}

