import { describe, it, expect } from "vitest";
import { execFileSync } from "node:child_process";
import { readFileSync, existsSync, statSync } from "node:fs";
import { countFastaKmers, countKmers, topK } from "./kmer.ts";

describe("k-mer counting", () => {
  it("counts ACGTACGT with k=4 exactly", () => {
    const counts = new Map<string, number>();
    const n = countKmers("ACGTACGT", 4, counts);
    expect(n).toBe(5); // 8 - 4 + 1 windows
    expect(counts.get("ACGT")).toBe(2);
    expect(counts.get("CGTA")).toBe(1);
    expect(counts.get("GTAC")).toBe(1);
    expect(counts.get("TACG")).toBe(1);
    expect(counts.size).toBe(4);
    expect(topK(counts, 10)[0]).toEqual(["ACGT", 2]);
  });

  it("generated FASTA exists and has expected size (50 x 100000 + headers/wrapping)", () => {
    if (!existsSync("sample.fa")) {
      execFileSync("node", ["--import", "tsx", "gen.ts"], { cwd: process.cwd() });
    }
    const st = statSync("sample.fa");
    // 50 records: header ">seqNNN\n" (8 bytes) + 100000 bases + 1666 newlines (ceil(100000/60) lines)
    const expected = 50 * (8 + 100_000 + Math.ceil(100_000 / 60));
    expect(st.size).toBe(expected);
  });

  it("global total window count equals 50 * (100000 - k + 1) for k=8", async () => {
    const { totalWindows } = await countFastaKmers("sample.fa", 8);
    expect(totalWindows).toBe(50 * (100_000 - 7));
  });

  it("per-record counts each sum to 99993 and match global aggregation", async () => {
    const { perRecordCounts, globalCounts } = await countFastaKmers("sample.fa", 8);
    const ids = [...perRecordCounts.keys()];
    expect(ids.length).toBe(50);
    expect(ids[0]).toBe("seq001");
    let sumPerRecord = 0;
    for (const m of perRecordCounts.values()) {
      let s = 0;
      for (const c of m.values()) s += c;
      expect(s).toBe(99_993);
      sumPerRecord += s;
    }
    let sumGlobal = 0;
    for (const c of globalCounts.values()) sumGlobal += c;
    expect(sumGlobal).toBe(sumPerRecord);
    // plain (non-canonical): both a kmer and its reverse complement counted separately
    expect(globalCounts.has("AAAAAAAT") || globalCounts.has("ATTTTTTT")).toBe(true);
  });
});

describe("timed full run under --max-old-space-size=512", () => {
  it("completes in under 10 seconds", () => {
    const t0 = Date.now();
    const out = execFileSync(
      "node",
      ["--max-old-space-size=512", "--import", "tsx", "kmer.ts", "sample.fa", "8"],
      { cwd: process.cwd(), encoding: "utf8", timeout: 10_000 },
    );
    const elapsed = Date.now() - t0;
    expect(elapsed).toBeLessThan(10_000);
    expect(out).toContain(`totalWindows=${50 * (100_000 - 7)}`);
    const topLines = out.split("\n").filter((l) => /^[ACGT]{8}\t\d+$/.test(l));
    expect(topLines.length).toBeGreaterThanOrEqual(10);
  }, 20_000);
});

// sanity: file content spot-check
describe("file format", () => {
  it("first line is a header and second is 60 bases of ACGT", () => {
    const head = readFileSync("sample.fa", "utf8").slice(0, 61);
    expect(head.startsWith(">seq001\n")).toBe(true);
    const firstSeqLine = head.split("\n")[1];
    expect(firstSeqLine).toMatch(/^[ACGT]{60}$/);
  });
});

